import re

def guarded_agent(agent, guardrails, input):
    for guard in guardrails.get("input_filter", []):
        if not guard(input):
            return {"status": "blocked", "reason": "Input blocked by guardrail", "safe": True}
    result = agent(input)
    action = result.get("action", result.get("tool", ""))
    for guard in guardrails.get("action_filter", []):
        if not guard(action):
            return {"status": "blocked", "reason": "Action blocked by guardrail", "safe": True}
    output = result.get("output", result.get("result", ""))
    for guard in guardrails.get("output_filter", []):
        if not guard(output):
            return {"status": "blocked", "reason": "Output blocked by guardrail", "safe": True}
    return {"status": "safe", "result": result, "safe": True}
